-- V9__baan_json_preset_seed.sql
-- Refresh local/demo BAAN preset data from tmp/baan-branch.json and tmp/baan-menu.json.

BEGIN;

INSERT INTO categories (id, company_id, slug, name, description, sort_order, is_active)
VALUES
  (1, 1, 'kaprao-signatures', 'Kaprao Signatures', 'BAAN-style basil rice signatures and spicy basil variations.', 1, TRUE),
  (2, 1, 'fried-rice-and-kua', 'Fried Rice & Kua Rice', 'Fried rice, kua-style rice, and wok-fired rice comfort dishes.', 2, TRUE),
  (3, 1, 'curries-and-spicy-rice', 'Curries & Spicy Rice', 'Green curry, red curry, tai pla, and stronger spice-led rice plates.', 3, TRUE),
  (4, 1, 'stir-fried-over-rice', 'Stir-fried Over Rice', 'Rice plates built around stir-fried toppings and wok mains.', 4, TRUE),
  (5, 1, 'grill-and-fried-favorites', 'Grill & Fried Favorites', 'Grilled pork neck, fried chicken, and heavier comfort mains.', 5, TRUE),
  (6, 1, 'vegetables-and-light', 'Vegetable & Light', 'Vegetable-forward, tofu, mushroom, and lighter rice dishes.', 6, TRUE),
  (7, 1, 'kid-favorites', 'Kid Favorites', 'Milder rice dishes and sausage or egg-forward comfort picks.', 7, TRUE),
  (8, 1, 'baan-specialties', 'BAAN Specialties', 'House-only combinations and one-off BAAN comfort plates.', 8, TRUE)
ON CONFLICT (id) DO UPDATE
SET company_id = EXCLUDED.company_id,
    slug = EXCLUDED.slug,
    name = EXCLUDED.name,
    description = EXCLUDED.description,
    sort_order = EXCLUDED.sort_order,
    is_active = EXCLUDED.is_active;

SELECT setval(pg_get_serial_sequence('categories', 'id'), GREATEST((SELECT MAX(id) FROM categories), 1), TRUE);

